import sys

MOD = 998244353

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    N = int(data[0])
    M = int(data[1])
    S = data[2]

    s = [ord(ch) - 97 for ch in S]
    states = 1 << N

    # row[mask][j] = LCS value for prefix S[:j]
    rows = []
    for mask in range(states):
        row = [0] * (N + 1)
        v = 0
        for j in range(1, N + 1):
            if (mask >> (j - 1)) & 1:
                v += 1
            row[j] = v
        rows.append(row)

    # Precompute transitions, aggregating characters with the same next state.
    trans = []
    for mask in range(states):
        row = rows[mask]
        d = {}
        for c in range(26):
            prev_old = 0   # old dp[j-1]
            prev_new = 0   # new dp[j-1]
            newmask = 0

            for j in range(1, N + 1):
                old_j = row[j]

                if s[j - 1] == c:
                    new_j = prev_old + 1
                else:
                    new_j = old_j if old_j > prev_new else prev_new

                if new_j > prev_new:
                    newmask |= 1 << (j - 1)

                prev_old = old_j
                prev_new = new_j

            d[newmask] = d.get(newmask, 0) + 1

        trans.append(tuple(d.items()))

    dp = [0] * states
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * states
        for mask, cnt in enumerate(dp):
            if cnt:
                for nxt, mult in trans[mask]:
                    ndp[nxt] += cnt * mult
        dp = [x % MOD for x in ndp]

    pop = [0] * states
    for mask in range(1, states):
        pop[mask] = pop[mask >> 1] + (mask & 1)

    ans = [0] * (N + 1)
    for mask, cnt in enumerate(dp):
        if cnt:
            ans[pop[mask]] = (ans[pop[mask]] + cnt) % MOD

    print(" ".join(map(str, ans)))

if __name__ == "__main__":
    solve()
