import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N, M = data[0], data[1]
    adj = [[] for _ in range(N)]

    idx = 2
    for _ in range(M):
        x = data[idx] - 1
        y = data[idx + 1] - 1
        z = data[idx + 2]
        idx += 3
        adj[x].append((y, z))
        adj[y].append((x, z))

    ans = [-1] * N

    for s in range(N):
        if ans[s] != -1:
            continue

        if not adj[s]:
            ans[s] = 0
            continue

        ans[s] = 0
        stack = [s]
        nodes = []
        max_val = 0

        while stack:
            v = stack.pop()
            nodes.append(v)
            av = ans[v]

            for to, w in adj[v]:
                nv = av ^ w
                if ans[to] == -1:
                    ans[to] = nv
                    if nv > max_val:
                        max_val = nv
                    stack.append(to)
                elif ans[to] != nv:
                    sys.stdout.write("-1\n")
                    return

        size = len(nodes)
        c = 0

        for b in range(max_val.bit_length()):
            mask = 1 << b
            cnt = 0
            for v in nodes:
                if ans[v] & mask:
                    cnt += 1
            if cnt * 2 > size:
                c |= mask

        if c:
            for v in nodes:
                ans[v] ^= c

    sys.stdout.write(" ".join(map(str, ans)) + "\n")


if __name__ == "__main__":
