def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    idx = 0
    N = data[idx]
    idx += 1

    K = [0] * N
    entries_by_value = {}

    for i in range(N):
        k = data[idx]
        idx += 1
        K[i] = k

        cnt = {}
        get = cnt.get
        end = idx + k
        while idx < end:
            v = data[idx]
            cnt[v] = get(v, 0) + 1
            idx += 1

        for v, c in cnt.items():
            lst = entries_by_value.get(v)
            if lst is None:
                entries_by_value[v] = [(i, c)]
            else:
                lst.append((i, c))

    # score[i][j] = sum_x count_i[x] * count_j[x]
    score = [[0] * N for _ in range(N)]

    for entries in entries_by_value.values():
        m = len(entries)
        if m == 2:
            (i, ci), (j, cj) = entries
            score[i][j] += ci * cj
        elif m > 2:
            for a in range(m - 1):
                i, ci = entries[a]
                row = score[i]
                for b in range(a + 1, m):
                    j, cj = entries[b]
                    row[j] += ci * cj

    best_num = 0
    best_den = 1

    for i in range(N - 1):
        ki = K[i]
        row = score[i]
        for j in range(i + 1, N):
            num = row[j]
            if num:
                den = ki * K[j]
                if num * best_den > best_num * den:
                    best_num = num
                    best_den = den

